 "content": "from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    def runs(row):
        out = []
        c = 0
        while c < w:
            color = row[c]
            end = c + 1
            while end < w and row[end] == color:
                end += 1
            if color != bg and end - c >= 2:
                out.append((color, c, end))
            c = end
        return out

    top_runs, bottom_runs = runs(g[0]), runs(g[-1])
    pairs = [(t, b) for t in top_runs for b in bottom_runs
             if t[0] == b[0] and t[2] - t[1] == b[2] - b[1]]
    if not pairs:
        return g
    (rail, top_start, top_end), (_, bottom_start, _) = pairs[0]
    for r in range(1, h - 1):
        for c in range(top_start, top_end):
            color = g[r][c]
            if color == bg or color == rail:
                continue
            # The marker projects toward the top rail; its cell is changed to 4.
            for rr in range(1, r):
                g[rr][c] = color
            g[r][c] = 4
            # Continue the same offset from the opposite rail all the way to the top.
            mate = bottom_start + (c - top_start)
            for rr in range(0, h - 1):
                g[rr][mate] = color
    return g
